    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    # Initialize DP arrays
    dp_left = [1] * n
    dp_right = [1] * n

    # Fill dp_left array
    for i in range(1, n):
        for j in range(i):
            if a[j] < a[i]:
                dp_left[i] = max(dp_left[i], dp_left[j] + 1)

    # Fill dp_right array
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if a[j] < a[i]:
                dp_right[i] = max(dp_right[i], dp_right[j] + 1)

    # Find the maximum length of increasing subsequence
    max_length = 0
    best_index = 0
    for i in range(n):
        if dp_left[i] + dp_right[i] - 1 > max_length:
            max_length = dp_left[i] + dp_right[i] - 1
            best_index = i

    # Reconstruct the sequence
    result = []
    current_length = dp_left[best_index]
    current_value = a[best_index]
    for i in range(best_index, -1, -1):
        if dp_left[i] == current_length and a[i] < current_value:
            result.append('L')
            current_length -= 1
            current_value = a[i]
