def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    left = 0
    right = n - 1
    result = []

    while left <= right:
        if left == right:
            result.append('L' if a[left] > (result[-1] if result else 0) else 'R')
            break

        if a[left] < a[right]:
            if not result or a[left] > result[-1]:
                result.append('L')
                left += 1
            else:
                result.append('R')
                right -= 1
        else:
            if not result or a[right] > result[-1]:
                result.append('R')
                right -= 1
            else:
                result.append('L')
                left += 1

    print(len(result))
    print(''.join(result))
